// HTML helpers + shared layout. `makeRender(L)` binds everything to one locale (see config.LOCALES).
const { SITE_URL, APP, ASSETS, SHOT_FILES, LOCALES } = require('./config');
const { URLS } = require('../constants');
const fs = require('fs');
const path = require('path');

// Read width/height from the PNG header at build time, so meta tags always match the file
// (preview images are regenerated by `npm run site:preview`). No native deps needed.
function pngSize(sitePath) {
    const buf = fs.readFileSync(path.join(__dirname, '..', '..', sitePath.replace(/^\//, '')));
    if (buf.toString('ascii', 12, 16) !== 'IHDR') throw new Error(`${sitePath} is not a PNG`);
    return { width: String(buf.readUInt32BE(16)), height: String(buf.readUInt32BE(20)) };
}

const esc = (s = '') => String(s)
    .replace(/&(?!(amp|lt|gt|quot|#\d+);)/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const strip = (s = '') => String(s).replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const abs = (p) => SITE_URL + String(p).replace(/^\//, '');
const jsonLd = (obj) => `<script type="application/ld+json">${JSON.stringify(obj).replace(/</g, '\\u003c')}</script>`;
const TRANSLIT = { а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'e', ж: 'zh', з: 'z', и: 'i', й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ф: 'f', х: 'kh', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'sch', ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya' };
const slugify = (s) => strip(s).toLowerCase().replace(/[а-яё]/g, (c) => TRANSLIT[c] ?? '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

function makeRender(L) {
    const t = L.t;
    const url = (p) => L.base + p;            // locale-relative path → site path
    const shotBase = (key) => `${L.shotDir}${SHOT_FILES[key]}`;

    function storeLink(location, inner, cls = 'store-badge') {
        return `<a class="${cls}" href="${APP.url}" rel="nofollow noopener" data-cta="${esc(location)}" aria-label="${esc(t.storeAria)}">${inner}</a>`;
    }
    function badge(location, extra = '') {
        return storeLink(location, `<img src="${ASSETS.badge}" alt="${esc(t.badgeAlt)}" width="180" height="60">`, `store-badge ${extra}`.trim());
    }
    function shot(key, { eager = false, sizes = '(max-width: 700px) 60vw, 260px', cls = '' } = {}) {
        const b = shotBase(key);
        return `<img class="shot ${cls}" src="${b}-390.webp" srcset="${b}-390.webp 390w, ${b}-780.webp 780w" sizes="${sizes}" width="390" height="844" alt="${esc(L.shots[key].alt)}" ${eager ? 'fetchpriority="high"' : 'loading="lazy"'} decoding="async">`;
    }
    function appIcon(size = 64, cls = 'app-icon', eager = false) {
        return `<img class="${cls}" src="${size > 180 ? ASSETS.icon512 : ASSETS.icon256}" width="${size}" height="${size}" alt="${esc(t.iconAlt)}" ${eager ? '' : 'loading="lazy"'} decoding="async">`;
    }

    function head({ title, description, path, ogType = 'website', schema = [], preloadHero = false, alternates = [] }) {
        const u = abs(path);
        const alt = alternates.length
            ? alternates.map(({ lang, url: au }) => `<link rel="alternate" hreflang="${lang}" href="${au}">`).join('\n    ') +
              `\n    <link rel="alternate" hreflang="x-default" href="${(alternates.find((a) => a.lang === 'en') || alternates[0]).url}">`
            : '';
        const hb = shotBase('clear');
        const og = pngSize(L.ogImage);
        return `<!DOCTYPE html>
<html lang="${L.lang}">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
    <title>${esc(title)}</title>
    <meta name="description" content="${esc(description)}">
    <meta name="robots" content="index, follow, max-image-preview:large, max-snippet:-1">
    <meta name="author" content="${esc(APP.developer)}">
    <link rel="canonical" href="${u}">
    ${alt}
    <meta property="og:type" content="${ogType}">
    <meta property="og:url" content="${u}">
    <meta property="og:title" content="${esc(title)}">
    <meta property="og:description" content="${esc(description)}">
    <meta property="og:image" content="${abs(L.ogImage)}">
    <meta property="og:image:width" content="${og.width}">
    <meta property="og:image:height" content="${og.height}">
    <meta property="og:image:alt" content="${esc(t.ogAlt)}">
    <meta property="og:site_name" content="${esc(L.siteName)}">
    <meta property="og:locale" content="${L.ogLocale}">
    <meta property="og:logo" content="${abs(ASSETS.icon512)}">
    <meta name="twitter:card" content="summary_large_image">
    <meta name="twitter:url" content="${u}">
    <meta name="twitter:title" content="${esc(title)}">
    <meta name="twitter:description" content="${esc(description)}">
    <meta name="twitter:image" content="${abs(L.ogImage)}">
    <meta name="twitter:image:width" content="${og.width}">
    <meta name="twitter:image:height" content="${og.height}">
    <meta name="apple-itunes-app" content="app-id=${APP.id}">
    <meta name="apple-mobile-web-app-title" content="Clear Wave">
    <meta name="theme-color" content="#1a0b45">
    <link rel="icon" type="image/x-icon" href="/favicon.ico">
    <link rel="icon" type="image/png" sizes="32x32" href="/favicon-32x32.png">
    <link rel="icon" type="image/png" sizes="16x16" href="/favicon-16x16.png">
    <link rel="apple-touch-icon" href="/apple-touch-icon.png">
    <link rel="manifest" href="/site.webmanifest">
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link rel="stylesheet" href="${L.fonts}">
    ${preloadHero ? `<link rel="preload" as="image" href="${hb}-390.webp" imagesrcset="${hb}-390.webp 390w, ${hb}-780.webp 780w" imagesizes="(max-width: 900px) 64vw, 280px" fetchpriority="high">` : ''}
    <link rel="stylesheet" href="/assets/site.css?v={{VERSION}}">
    ${schema.map(jsonLd).join('\n    ')}
    <script async src="https://www.googletagmanager.com/gtag/js?id=G-G4CQ97HTGF"></script>
    <script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag('js',new Date());gtag('config','G-G4CQ97HTGF');</script>
</head>`;
    }

    function nav(current = '') {
        const link = (href, label, key) => `<a href="${href}"${current === key ? ' aria-current="page"' : ''}>${label}</a>`;
        return `
<a class="skip" href="#main">${t.skip}</a>
<header class="site-header">
    <div class="wrap nav">
        <a class="brand" href="${L.base}" aria-label="${esc(t.homeAria)}">
            <img src="${ASSETS.icon256}" width="36" height="36" alt="" decoding="async">
            <span>Clear Wave</span>
        </a>
        <nav class="nav-links" aria-label="${esc(t.mainNav)}">
            ${link(`${L.base}#how-it-works`, t.navHow, 'how')}
            ${link(url('guides/'), t.navGuides, 'guides')}
            ${link(url('faq/'), t.navFaq, 'faq')}
        </nav>
        ${storeLink('nav', t.getApp, 'btn btn-small')}
    </div>
</header>`;
    }

    function stickyBar() {
        return `
<div class="sticky-cta" data-sticky hidden>
    <img src="${ASSETS.icon256}" width="40" height="40" alt="" decoding="async">
    <div><strong>Clear Wave</strong><span>${t.stickySub}</span></div>
    ${storeLink('sticky', t.stickyGet, 'btn btn-small')}
</div>`;
    }

    function footer(guides, faqs) {
        const langs = URLS.map((u) => `<a href="${u.lang === 'en' ? '/' : `/${u.lang}/`}" hreflang="${u.lang}"${u.lang === L.lang ? ' aria-current="true"' : ''}>${u.lang.toUpperCase()}</a>`).join(' ');
        return `
<footer class="site-footer">
    <div class="wrap footer-grid">
        <div class="footer-brand">
            <a class="brand" href="${L.base}"><img src="${ASSETS.icon256}" width="44" height="44" alt="" loading="lazy"><span>Clear Wave</span></a>
            <p>${t.footerAbout}</p>
            ${badge('footer')}
        </div>
        <div>
            <h2 class="footer-h">${t.footerGuides}</h2>
            <ul>${guides.map((g) => `<li><a href="${url(`guides/${g.slug}/`)}">${esc(g.navLabel || g.h1)}</a></li>`).join('')}</ul>
        </div>
        <div>
            <h2 class="footer-h">${t.footerQuestions}</h2>
            <ul>${faqs.map((f) => `<li><a href="${url(`faq/${f.slug}/`)}">${esc(f.question)}</a></li>`).join('')}</ul>
        </div>
        <div>
            <h2 class="footer-h">${t.footerApp}</h2>
            <ul>
                <li><a href="${APP.url}" rel="nofollow noopener">${t.footerDownload}</a></li>
                <li><a href="/privacy.html">${t.privacy}</a></li>
                <li><a href="/terms.html">${t.terms}</a></li>
                <li><a href="/llms.txt">llms.txt</a></li>
            </ul>
            <h2 class="footer-h">${t.languages}</h2>
            <p class="langs">${langs}</p>
        </div>
    </div>
    <div class="wrap footer-base">
        <span>© ${new Date().getFullYear()} c-basso · ${esc(APP.developer)}. ${t.legal}</span>
    </div>
</footer>`;
    }

    function scripts() {
        return `
<script src="/assets/site.js?v={{VERSION}}" defer></script>
<script>
(function(m,e,t,r,i,k,a){m[i]=m[i]||function(){(m[i].a=m[i].a||[]).push(arguments)};m[i].l=1*new Date();for(var j=0;j<document.scripts.length;j++){if(document.scripts[j].src===r){return;}}k=e.createElement(t),a=e.getElementsByTagName(t)[0],k.async=1,k.src=r,a.parentNode.insertBefore(k,a)})(window,document,"script","https://mc.yandex.ru/metrika/tag.js","ym");
ym(103203417,"init",{clickmap:true,trackLinks:true,accurateTrackBounce:true,webvisor:true});
</script>
<noscript><div><img src="https://mc.yandex.ru/watch/103203417" style="position:absolute;left:-9999px" alt=""></div></noscript>`;
    }

    // ---------- Schema ----------
    const home = abs(L.base);
    function schemaApp() {
        return {
            '@context': 'https://schema.org', '@type': 'MobileApplication',
            name: `${APP.brand} – ${L.storeName}`, alternateName: [L.storeName, APP.brand],
            description: t.schemaAppDesc, url: home, inLanguage: L.lang,
            applicationCategory: 'MusicApplication', applicationSubCategory: t.schemaSub,
            operatingSystem: `iOS ${APP.minIOS}+`, softwareVersion: APP.version, fileSize: APP.size,
            downloadUrl: APP.url, installUrl: APP.url, image: abs(ASSETS.icon512),
            screenshot: Object.keys(SHOT_FILES).map((k) => abs(`${shotBase(k)}-780.webp`)),
            offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD', availability: 'https://schema.org/InStock' },
            aggregateRating: { '@type': 'AggregateRating', ratingValue: APP.rating, ratingCount: APP.ratingCount, bestRating: '5', worstRating: '1' },
            author: { '@type': 'Person', name: APP.developer },
            publisher: { '@id': `${SITE_URL}#org` }
        };
    }
    function schemaOrg() {
        return { '@context': 'https://schema.org', '@type': 'Organization', '@id': `${SITE_URL}#org`, name: 'Clear Wave', url: SITE_URL, logo: abs(ASSETS.icon512), founder: { '@type': 'Person', name: APP.developer }, foundingDate: '2025', sameAs: [APP.url] };
    }
    function schemaWebsite() {
        return { '@context': 'https://schema.org', '@type': 'WebSite', '@id': `${home}#website`, name: L.siteName, url: home, inLanguage: L.lang, publisher: { '@id': `${SITE_URL}#org` } };
    }
    function schemaBreadcrumb(items) {
        return { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: items.map((it, i) => ({ '@type': 'ListItem', position: i + 1, name: strip(it.name), item: abs(it.path) })) };
    }
    function schemaFaq(list) {
        return { '@context': 'https://schema.org', '@type': 'FAQPage', inLanguage: L.lang, mainEntity: list.map((f) => ({ '@type': 'Question', name: strip(f.q), acceptedAnswer: { '@type': 'Answer', text: strip(f.a) } })) };
    }
    function schemaHowTo({ name, description, steps, totalTime = 'PT2M', image }) {
        return {
            '@context': 'https://schema.org', '@type': 'HowTo', name: strip(name), description: strip(description), totalTime, inLanguage: L.lang,
            ...(image ? { image } : {}),
            tool: [{ '@type': 'HowToTool', name: t.howToTool }],
            step: steps.map((s, i) => ({ '@type': 'HowToStep', position: i + 1, name: strip(s.name), text: strip(s.text) }))
        };
    }
    function schemaArticle({ headline, description, path, datePublished, dateModified, image }) {
        return {
            '@context': 'https://schema.org', '@type': 'Article', headline: strip(headline), description, inLanguage: L.lang,
            mainEntityOfPage: abs(path), image: image || abs(L.ogImage), datePublished, dateModified,
            author: { '@type': 'Person', name: APP.developer }, publisher: { '@id': `${SITE_URL}#org` },
            about: { '@type': 'MobileApplication', name: `${APP.brand} – ${L.storeName}`, url: APP.url }
        };
    }

    function breadcrumbHtml(items) {
        return `<nav class="crumbs" aria-label="${esc(t.crumbAria)}"><ol>${items.map((it, i) => i === items.length - 1
            ? `<li aria-current="page">${esc(it.name)}</li>`
            : `<li><a href="${it.path}">${esc(it.name)}</a></li>`).join('')}</ol></nav>`;
    }

    function appCard(location, { title = t.appCardTitle, text = t.appCardText, shotKey = 'cover' } = {}) {
        return `
<aside class="app-card" aria-label="${esc(t.appCardAria)}">
    <div class="app-card__shot">${shot(shotKey, { sizes: '160px' })}</div>
    <div class="app-card__body">
        <p class="eyebrow">${t.appCardEyebrow}</p>
        <h2 class="app-card__title">${title}</h2>
        <p>${text}</p>
        <div class="app-card__row">
            ${badge(location)}
            <span class="app-card__meta">${t.appCardMeta}</span>
        </div>
    </div>
</aside>`;
    }

    function finalCta(location, heading = t.ctaHeading) {
        return `
<section class="final-cta" aria-labelledby="cta-${location}">
    <div class="rings" aria-hidden="true"><span></span><span></span><span></span></div>
    <div class="wrap final-cta__inner">
        ${appIcon(96, 'final-cta__icon')}
        <h2 id="cta-${location}">${heading}</h2>
        <p>${t.ctaText}</p>
        <div class="cta-row">
            ${badge(location)}
            <img class="qr" src="${ASSETS.qr}" width="96" height="96" alt="${esc(t.qrAlt)}" loading="lazy">
        </div>
    </div>
</section>`;
    }

    return {
        L, t, url, esc, strip, abs, slugify, head, nav, footer, scripts, stickyBar, badge, storeLink, shot, appIcon,
        appCard, finalCta, breadcrumbHtml,
        schemaApp, schemaOrg, schemaWebsite, schemaBreadcrumb, schemaFaq, schemaHowTo, schemaArticle
    };
}

module.exports = { makeRender, esc, strip, abs, slugify, LOCALES, APP, ASSETS };
